from pathlib import Path
from html import escape
root=Path(__file__).parent
base='https://aonetaxiservices.ca/'

def ic(n):
 from xml.etree import ElementTree as ET
 from xml.sax.saxutils import escape as esc
 root_svg=ET.parse(root/'assets/icons.svg').getroot()
 sym=next((el for el in root_svg if el.get('id')==n),None)
 assert sym is not None,n
 return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+''.join(ET.tostring(e,encoding='unicode').replace('ns0:','').replace(' xmlns:ns0="http://www.w3.org/2000/svg"','') for e in sym)+'</svg>'

